1	<!DOCTYPE html>
2	<html lang="zh-CN">
3	<head>
4	<meta charset="UTF-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1.0">
6	<title>LoLM 英雄梯度排行榜</title>
7	<style>
8	* { margin: 0; padding: 0; box-sizing: border-box; }
9	body {
10	    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", "PingFang SC",
11	                 "Microsoft YaHei", sans-serif;
12	    background: #0d1117;
13	    color: #c9d1d9;
14	    min-height: 100vh;
15	}
16	.header {
17	    background: linear-gradient(135deg, #1a1a2e 0%, #16213e 50%, #0f3460 100%);
18	    padding: 32px 24px;
19	    text-align: center;
20	    border-bottom: 1px solid #30363d;
21	}
22	.header h1 { font-size: 2rem; color: #f0f6fc; }
23	
24	/* 导航 */
25	.nav {
26	    display: flex; justify-content: center; gap: 4px;
27	    padding: 16px 24px; background: #161b22;
28	    border-bottom: 1px solid #30363d; position: sticky; top: 0; z-index: 100;
