38	
39	/* 方法切换 & 视图切换 */
40	.controls {
41	    display: flex; justify-content: center; align-items: center; gap: 16px;
42	    padding: 12px 24px; flex-wrap: wrap;
43	}
44	.controls .label { color: #8b949e; font-size: 0.8rem; margin-right: 2px; }
45	.controls button {
46	    background: transparent; color: #8b949e; border: 1px solid #30363d;
47	    padding: 5px 14px; border-radius: 4px; cursor: pointer; font-size: 0.8rem;
48	}
49	.controls button.active { background: #238636; border-color: #238636; color: #fff; }
