64	    background: #161b22; border: 1px solid #30363d; border-radius: 8px;
65	    padding: 12px 16px; flex: 1; min-width: 90px; text-align: center;
66	}
67	.stat-card .stat-value { font-size: 1.4rem; font-weight: 700; color: #f0f6fc; }
68	.stat-card .stat-label { font-size: 0.75rem; color: #8b949e; margin-top: 2px; }
69	
70	/* 表格 */
71	.table-wrapper { overflow-x: auto; border-radius: 8px; border: 1px solid #30363d; }
72	table { width: 100%; border-collapse: collapse; font-size: 0.9rem; }
73	thead th {
74	    background: #161b22; color: #8b949e; padding: 12px 14px;
75	    text-align: left; font-weight: 600; border-bottom: 1px solid #30363d;
76	    white-space: nowrap; position: sticky; top: 0; cursor: pointer; user-select: none;
77	}
78	thead th:hover { color: #f0f6fc; }
79	thead th .sort-icon { opacity: 0.3; margin-left: 4px; }
80	thead th.sorted .sort-icon { opacity: 1; }
81	tbody td { padding: 10px 14px; border-bottom: 1px solid #21262d; }
82	tbody tr:hover { background: rgba(255,255,255,0.03); }
83	
84	.rank-num { font-weight: 700; font-size: 1rem; color: #f0f6fc; text-align: center; }
85	.rank-1 { color: #ffd700; font-size: 1.3rem; }
86	.rank-2 { color: #c0c0c0; font-size: 1.2rem; }
87	.rank-3 { color: #cd7f32; font-size: 1.1rem; }
88	
89	.tier-badge {
90	    display: inline-block; padding: 3px 10px; border-radius: 4px;
91	    font-weight: 700; font-size: 0.8rem; color: #fff; text-align: center; min-width: 44px;
92	}
93	
94	.score-bar-wrap { display: flex; align-items: center; gap: 8px; min-width: 120px; }
95	.score-bar { flex: 1; height: 6px; background: #21262d; border-radius: 3px; overflow: hidden; }
96	.score-bar-fill { height: 100%; border-radius: 3px; transition: width 0.3s; }
97	.score-value { font-weight: 600; font-size: 0.85rem; color: #f0f6fc; min-width: 44px; text-align: right; }
98	
99	.hero-name { font-weight: 600; color: #f0f6fc; }
100	
101	.wr-high { color: #3fb950; font-weight: 600; }
102	.wr-mid { color: #d29922; }
103	.wr-low { color: #f85149; }
104	
105	/* 全局排名高亮当前分路 */
106	tr.current-lane-highlight { background: rgba(31,111,235,0.08); }
107	
108	/* 搜索框 */
109	.search-box {
110	    background: #21262d; border: 1px solid #30363d; border-radius: 6px;
111	    padding: 8px 14px; color: #c9d1d9; font-size: 0.9rem; width: 200px;
112	    outline: none;
113	}
114	.search-box:focus { border-color: #1f6feb; }
115	.search-box::placeholder { color: #484f58; }
116	
117	/* 页脚 */
118	.footer {
119	    text-align: center; padding: 24px; color: #484f58;
120	    font-size: 0.8rem; border-top: 1px solid #30363d; margin-top: 24px;
121	}
122	
123	/* 响应式 */
124	@media (max-width: 768px) {
125	    .header h1 { font-size: 1.4rem; }
126	    .nav button { padding: 6px 12px; font-size: 0.8rem; }
127	    table { font-size: 0.75rem; }
128	    .stats-row { gap: 6px; }
129	    .stat-card { padding: 8px 10px; }
130	    .controls { gap: 6px; }
131	    .controls button { padding: 4px 8px; font-size: 0.7rem; }
132	}
133	</style>
134	</head>
135	<body>
136	
137	<div class="header">
138	    <h1>⚔️ LoLM 英雄梯度排行榜</h1>
139	</div>
140	
141	<div class="nav" id="nav"></div>
142	
143	<div class="controls">
144	    <span class="label">算法：</span>
145	    <button class="active" onclick="switchMethod('zscore')">Z-score 加权</button>
146	    <button onclick="switchMethod('simple')">简易公式</button>
147	    <span style="margin-left:16px" class="label">视图：</span>
148	    <button id="btn-lane" class="active" onclick="switchView('lane')">📋 分路排名</button>
149	    <button id="btn-global" onclick="switchView('global')">🌍 全局排名</button>
150	    <input type="text" class="search-box" placeholder="🔍 搜索英雄..." oninput="doSearch(this.value)" style="margin-left:16px">
151	</div>
152	
153	<div class="container" id="content"></div>
154	
155	<div class="footer">
156	    LoLM Hero Tier List · 算法来源于王者荣耀梯度逆推分析 · 仅供参考
157	</div>
158	
159	<script>
160	// ============================================================
161	// 从 JSON 文件加载数据
162	// ============================================================
163	let RAW_DATA = {};
164	
165	const LANE_FILES = {
166	    "上路": "上路.json",
167	    "打野": "打野.json",
168	    "中路": "中路.json",
169	    "下路": "下路.json",
170	    "辅助": "辅助.json"
171	};
172	
173	async function loadData() {
174	    const entries = Object.entries(LANE_FILES);
175	    const results = await Promise.all(
176	        entries.map(async ([laneName, filePath]) => {
177	            const resp = await fetch(filePath);
178	            if (!resp.ok) throw new Error(`加载 ${filePath} 失败: ${resp.status}`);
179	            const data = await resp.json();
180	            return [laneName, data];
181	        })
182	    );
183	    RAW_DATA = Object.fromEntries(results);
184	}
185	
186	// ============================================================
187	// 算法配置
188	// ============================================================
189	const Z_WEIGHTS = { wr: 0.5, pr: 1.0, br: 3.0 };
190	const SIMPLE_WR_EXP = 0.3;
191	const SIMPLE_BR_BOOST = 2.5;
192	
193	const TIER_THRESHOLDS = [
194	    { tier: "T0",   pct: 0.92 },
195	    { tier: "T0.5", pct: 0.88 },
196	    { tier: "T1",   pct: 0.70 },
197	    { tier: "T2",   pct: 0.40 },
198	    { tier: "T3",   pct: 0.12 },
199	    { tier: "T4",   pct: 0.00 }
200	];
201	
202	const TIER_COLORS = {
203	    "T0":   "#ff4d4f",
204	    "T0.5": "#ff7a45",
205	    "T1":   "#ffa940",
206	    "T2":   "#ffc53d",
207	    "T3":   "#73d13d",
208	    "T4":   "#8c8c8c"
209	};
210	
211	const TIER_ORDER = ["T0", "T0.5", "T1", "T2", "T3", "T4"];
212	
213	// ============================================================
214	// 计算引擎
215	// ============================================================
216	let computedData = null;  // { lanes: { laneName: [hero, ...] }, globalZ: [hero,...], globalSimple: [hero,...] }
217	let currentMethod = "zscore";
218	let currentView = "lane";
219	let currentLane = null;
220	
221	function parsePct(s) {
222	    return parseFloat(s.replace("%", "")) / 100.0;
223	}
224	
225	function mean(arr) {
226	    return arr.reduce((a, b) => a + b, 0) / arr.length;
227	}
228	
229	function stdDev(arr) {
230	    const m = mean(arr);
231	    const variance = arr.reduce((s, v) => s + (v - m) ** 2, 0) / arr.length;
232	    return Math.sqrt(variance) || 1.0;
233	}
234	
235	function zScores(arr) {
236	    const m = mean(arr);
237	    const s = stdDev(arr);
238	    if (s === 0) return arr.map(() => 0);
239	    return arr.map(v => (v - m) / s);
240	}
241	
242	function computeAll() {
243	    const lanes = {};
244	    const allHeroes = [];
245	
246	    // 解析数据
247	    for (const [laneName, rawHeroes] of Object.entries(RAW_DATA)) {
248	        const heroes = rawHeroes.map(h => ({
249	            name: h.heroName,
250	            lane: laneName,
251	            wr: parsePct(h.winRate),
252	            pr: parsePct(h.pickRate),
253	            br: parsePct(h.banRate),
254	            bp: parsePct(h.pickRate) + parsePct(h.banRate)
255	        }));
256	        lanes[laneName] = heroes;
257	        allHeroes.push(...heroes);
258	    }
259	
260	    // ---- 方法1: Z-score 加权 ----
261	    for (const [laneName, heroes] of Object.entries(lanes)) {
262	        const zWr = zScores(heroes.map(h => h.wr));
263	        const zPr = zScores(heroes.map(h => h.pr));
264	        const zBr = zScores(heroes.map(h => h.br));
265	        heroes.forEach((h, i) => {
266	            h.z_wr = zWr[i];
267	            h.z_pr = zPr[i];
268	            h.z_br = zBr[i];
269	            h.raw_zscore = Z_WEIGHTS.wr * zWr[i] + Z_WEIGHTS.pr * zPr[i] + Z_WEIGHTS.br * zBr[i];
270	        });
271	    }
272	
273	    // ---- 方法2: 简易公式 ----
274	    for (const [laneName, heroes] of Object.entries(lanes)) {
275	        heroes.forEach(h => {
276	            h.raw_simple = Math.pow(h.wr, SIMPLE_WR_EXP) * (h.pr + SIMPLE_BR_BOOST * h.br) * 100;
277	        });
278	    }
279	
280	    // ---- 分路内归一化 ----
281	    for (const [laneName, heroes] of Object.entries(lanes)) {
282	        normalizeLane(heroes, "raw_zscore", "score_zscore");
283	        normalizeLane(heroes, "raw_simple", "score_simple");
284	    }
285	
286	    // ---- 全局归一化 ----
287	    normalizeGlobal(allHeroes, "raw_zscore", "score_zscore_global");
288	    normalizeGlobal(allHeroes, "raw_simple", "score_simple_global");
289	
290	    // ---- 分配梯度 ----
291	    for (const [laneName, heroes] of Object.entries(lanes)) {
292	        assignTiers(heroes, "score_zscore", "tier_zscore", "lane_rank_zscore");
293	        assignTiers(heroes, "score_simple", "tier_simple", "lane_rank_simple");
294	        assignTiers(heroes, "score_zscore_global", "tier_global", "lane_rank_global");
295	    }
296	
297	    // ---- 全局排名 ----
298	    const globalZ = [...allHeroes].sort((a, b) => b.score_zscore_global - a.score_zscore_global);
299	    globalZ.forEach((h, i) => h.global_rank_zscore = i + 1);
300	
301	    const globalSimple = [...allHeroes].sort((a, b) => b.score_simple_global - a.score_simple_global);
302	    globalSimple.forEach((h, i) => h.global_rank_simple = i + 1);
303	
304	    computedData = { lanes, globalZ, globalSimple, totalHeroes: allHeroes.length };
305	}
306	
307	function normalizeLane(heroes, rawKey, normKey) {
308	    const vals = heroes.map(h => h[rawKey]);
309	    const vMin = Math.min(...vals);
310	    const vMax = Math.max(...vals);
311	    const rng = vMax - vMin || 1;
312	    heroes.forEach(h => {
313	        h[normKey] = ((h[rawKey] - vMin) / rng) * 100;
314	    });
315	}
316	
317	function normalizeGlobal(heroes, rawKey, normKey) {
318	    const vals = heroes.map(h => h[rawKey]);
319	    const vMin = Math.min(...vals);
320	    const vMax = Math.max(...vals);
321	    const rng = vMax - vMin || 1;
322	    heroes.forEach(h => {
323	        h[normKey] = ((h[rawKey] - vMin) / rng) * 100;
324	    });
325	}
326	
327	function assignTiers(heroes, scoreKey, tierKey, rankKey) {
328	    const sorted = [...heroes].sort((a, b) => b[scoreKey] - a[scoreKey]);
329	    const n = sorted.length;
330	    sorted.forEach((h, rank) => {
331	        const pct = 1.0 - (rank / n);
332	        let tier = "T4";
333	        for (const t of TIER_THRESHOLDS) {
334	            if (pct >= t.pct) { tier = t.tier; break; }
335	        }
336	        h[tierKey] = tier;
337	        h[rankKey] = rank + 1;
338	    });
339	}
340	
341	// ============================================================
342	// 渲染
343	// ============================================================
344	function getScoreKey() {
345	    return currentMethod === "zscore" ? "score_zscore" : "score_simple";
346	}
347	
348	function getTierKey() {
349	    return currentMethod === "zscore" ? "tier_zscore" : "tier_simple";
350	}
351	
352	function getRankKey() {
353	    return currentMethod === "zscore" ? "lane_rank_zscore" : "lane_rank_simple";
354	}
355	
356	function getGlobalRankKey() {
357	    return currentMethod === "zscore" ? "global_rank_zscore" : "global_rank_simple";
358	}
359	
360	function getScoreBar(score, tier) {
361	    const color = TIER_COLORS[tier] || "#8c8c8c";
362	    return `<div class="score-bar-wrap">
363	        <div class="score-bar"><div class="score-bar-fill" style="width:${score}%;background:${color}"></div></div>
364	        <span class="score-value">${score.toFixed(1)}</span></div>`;
365	}
366	
367	function getTierBadge(tier) {
368	    const color = TIER_COLORS[tier] || "#8c8c8c";
369	    return `<span class="tier-badge" style="background:${color}">${tier}</span>`;
370	}
371	
372	function getWrClass(wr) {
373	    if (wr >= 52) return "wr-high";
374	    if (wr >= 49) return "wr-mid";
375	    return "wr-low";
376	}
377	
378	function getRankClass(rank) {
379	    if (rank === 1) return "rank-1";
380	    if (rank === 2) return "rank-2";
381	    if (rank === 3) return "rank-3";
382	    return "";
383	}
384	
385	function renderLaneView(laneName) {
386	    const heroes = computedData.lanes[laneName];
387	    if (!heroes) return "<p>无数据</p>";
388	
389	    const scoreKey = getScoreKey();
390	    const tierKey = getTierKey();
391	    const rankKey = getRankKey();
392	    const globalRankKey = getGlobalRankKey();
393	
394	    // 统计
395	    const wrVals = heroes.map(h => h.wr * 100);
396	    const prVals = heroes.map(h => h.pr * 100);
397	    const brVals = heroes.map(h => h.br * 100);
398	    const avgWr = mean(wrVals);
399	    const avgPr = mean(prVals);
400	    const avgBr = mean(brVals);
401	
402	    // 按分路排名排序
403	    const sorted = [...heroes].sort((a, b) => a[rankKey] - b[rankKey]);
404	
405	    let html = `
406	    <div class="lane-header">
407	        <h2>${laneName}</h2>
408	        <span class="hero-count">${heroes.length} 个英雄</span>
409	    </div>
410	    <div class="stats-row">
411	        <div class="stat-card"><div class="stat-value">${avgWr.toFixed(1)}%</div><div class="stat-label">平均胜率</div></div>
412	        <div class="stat-card"><div class="stat-value">${avgPr.toFixed(1)}%</div><div class="stat-label">平均出场率</div></div>
413	        <div class="stat-card"><div class="stat-value">${avgBr.toFixed(1)}%</div><div class="stat-label">平均Ban率</div></div>
414	    </div>
415	    <div class="table-wrapper">
416	        <table>
417	            <thead><tr>
418	                <th onclick="sortLaneTable(this, 0)"># <span class="sort-icon">↕</span></th>
419	                <th onclick="sortLaneTable(this, 1)">英雄 <span class="sort-icon">↕</span></th>
420	                <th onclick="sortLaneTable(this, 2)">梯度 <span class="sort-icon">↕</span></th>
421	                <th onclick="sortLaneTable(this, 3)">评分 <span class="sort-icon">↕</span></th>
422	                <th onclick="sortLaneTable(this, 4)">胜率 <span class="sort-icon">↕</span></th>
423	                <th onclick="sortLaneTable(this, 5)">出场率 <span class="sort-icon">↕</span></th>
424	                <th onclick="sortLaneTable(this, 6)">Ban率 <span class="sort-icon">↕</span></th>
425	                <th onclick="sortLaneTable(this, 7)">BP率 <span class="sort-icon">↕</span></th>
426	                <th onclick="sortLaneTable(this, 8)">全局排名 <span class="sort-icon">↕</span></th>
427	            </tr></thead>
428	            <tbody>`;
429	
430	    sorted.forEach(h => {
431	        html += `<tr>
432	            <td class="rank-num ${getRankClass(h[rankKey])}">${h[rankKey]}</td>
433	            <td class="hero-name">${h.name}</td>
434	            <td>${getTierBadge(h[tierKey])}</td>
435	            <td>${getScoreBar(h[scoreKey], h[tierKey])}</td>
436	            <td class="${getWrClass(h.wr * 100)}">${(h.wr * 100).toFixed(2)}%</td>
437	            <td>${(h.pr * 100).toFixed(2)}%</td>
438	            <td>${(h.br * 100).toFixed(2)}%</td>
439	            <td>${(h.bp * 100).toFixed(2)}%</td>
440	            <td style="color:#8b949e">#${h[globalRankKey]}</td>
441	        </tr>`;
442	    });
443	
444	    html += `</tbody></table></div>`;
445	    return html;
446	}
447	
448	function renderGlobalView() {
449	    const scoreKey = currentMethod === "zscore" ? "score_zscore_global" : "score_simple_global";
450	    const tierKey = "tier_global";
451	    const globalRankKey = getGlobalRankKey();
452	    const all = currentMethod === "zscore" ? computedData.globalZ : computedData.globalSimple;
453	
454	    let html = `
455	    <div class="lane-header">
456	        <h2>🌍 全局排名（跨分路对比）</h2>
457	        <span class="hero-count">${all.length} 个英雄</span>
458	    </div>
459	    <p style="color:#8b949e;margin-bottom:16px;font-size:0.9rem;">
460	        ⚠️ 全局排名仅供参考。不同分路英雄职责不同，直接比较评分存在偏差，建议以分路内排名为主。
461	    </p>
462	    <div class="table-wrapper">
463	        <table>
464	            <thead><tr>
465	                <th onclick="sortGlobalTable(this, 0)"># <span class="sort-icon">↕</span></th>
466	                <th onclick="sortGlobalTable(this, 1)">英雄 <span class="sort-icon">↕</span></th>
467	                <th onclick="sortGlobalTable(this, 2)">分路 <span class="sort-icon">↕</span></th>
468	                <th onclick="sortGlobalTable(this, 3)">分路梯度 <span class="sort-icon">↕</span></th>
469	                <th onclick="sortGlobalTable(this, 4)">全局评分 <span class="sort-icon">↕</span></th>
470	                <th onclick="sortGlobalTable(this, 5)">胜率 <span class="sort-icon">↕</span></th>
471	                <th onclick="sortGlobalTable(this, 6)">出场率 <span class="sort-icon">↕</span></th>
472	                <th onclick="sortGlobalTable(this, 7)">Ban率 <span class="sort-icon">↕</span></th>
473	                <th onclick="sortGlobalTable(this, 8)">BP率 <span class="sort-icon">↕</span></th>
474	            </tr></thead>
475	            <tbody>`;
476	
477	    all.forEach(h => {
478	        const laneTierKey = getTierKey();
479	        html += `<tr>
480	            <td class="rank-num ${getRankClass(h[globalRankKey])}">${h[globalRankKey]}</td>
481	            <td class="hero-name">${h.name}</td>
482	            <td style="color:#8b949e">${h.lane}</td>
483	            <td>${getTierBadge(h[laneTierKey])}</td>
484	            <td>${getScoreBar(h[scoreKey], h[tierKey])}</td>
