612	function sortLaneTable(th, colIdx) {
613	    const table = th.closest("table");
614	    const tbody = table.querySelector("tbody");
615	    const rows = Array.from(tbody.querySelectorAll("tr"));
616	    const isDesc = th.classList.contains("sorted") && !th.classList.contains("desc");
617	
618	    table.querySelectorAll("th").forEach(h => { h.classList.remove("sorted", "desc"); });
619	    th.classList.add("sorted");
620	    if (isDesc) th.classList.add("desc");
621	
622	    rows.sort((a, b) => {
623	        let va = a.cells[colIdx].textContent.replace(/[#%]/g, "").trim();
624	        let vb = b.cells[colIdx].textContent.replace(/[#%]/g, "").trim();
625	
626	        if (colIdx === 2) {
627	            va = TIER_ORDER.indexOf(va);
628	            vb = TIER_ORDER.indexOf(vb);
629	        }
630	        const na = parseFloat(va);
631	        const nb = parseFloat(vb);
632	        if (!isNaN(na) && !isNaN(nb)) {
633	            return isDesc ? nb - na : na - nb;
634	        }
635	        return isDesc ? vb.localeCompare(va) : va.localeCompare(vb);
636	    });
637	    rows.forEach(r => tbody.appendChild(r));
638	}
