143	    <script>
144	        // --- DOM 元素 ---
145	        const selectFolderBtn = document.getElementById('selectFolderBtn');
146	        const folderDisplay = document.getElementById('folderDisplay');
147	        const sheetSelector = document.getElementById('sheetSelector');
148	        const intervalInput = document.getElementById('intervalInput');
149	        const startBtn = document.getElementById('startBtn');
150	        const stopBtn = document.getElementById('stopBtn');
151	        const clearAuthBtn = document.getElementById('clearAuthBtn');
152	        const container = document.getElementById('table-container');
153	        const statusDiv = document.getElementById('status');
154	
155	        // --- 状态变量 ---
156	        let folderHandle = null;
157	        let folderName = '';
158	        let refreshInterval = null;
159	        let currentData = [];          // 二维数组 (不含表头)
160	        let currentHeaders = [];
161	        let sortColumn = -1;
162	        let sortAsc = true;
163	        let excelFileName = '';        // 当前监控的 Excel 文件名
164	        let workbookData = null;       // 缓存 workbook 对象，用于切换工作表
165	
166	        // --- 存储 KEY ---
167	        const STORAGE_KEY = 'excel_monitor_folder_permission';
168	
169	        // --- 尝试从 localStorage 恢复（仅恢复名称提示） ---
170	        function restorePermission() {
171	            try {
172	                const stored = localStorage.getItem(STORAGE_KEY);
173	                if (stored) {
174	                    const { folderName: name } = JSON.parse(stored);
175	                    folderName = name || '';
176	                    folderDisplay.textContent = `📁 ${folderName} (需重新授权)`;
177	                    statusDiv.textContent = '⚠️ 授权已过期，请重新点击「选择文件夹并授权」';
178	                }
179	            } catch (e) { }
