182	        // --- 选择文件夹并授权 ---
183	        async function selectFolder() {
184	            try {
185	                const handle = await window.showDirectoryPicker();
186	                const opts = { mode: 'read' };
187	                const permission = await handle.requestPermission(opts);
188	                if (permission === 'granted') {
189	                    folderHandle = handle;
190	                    folderName = handle.name;
191	                    folderDisplay.textContent = `📁 ${folderName} (已授权)`;
192	                    statusDiv.textContent = `✅ 已授权文件夹: ${folderName}`;
193	                    localStorage.setItem(STORAGE_KEY, JSON.stringify({ folderName }));
194	                    // 自动查找并加载第一个 Excel
195	                    await findAndLoadFirstExcel();
196	                } else {
197	                    statusDiv.textContent = '❌ 授权被拒绝';
198	                }
199	            } catch (err) {
200	                if (err.name === 'AbortError' || err.message?.includes('abort')) {
201	                    statusDiv.textContent = 'ℹ️ 用户取消了选择';
202	                } else {
203	                    statusDiv.textContent = `❌ 出错: ${err.message}`;
204	                    console.error(err);
