209	        // --- 在文件夹中查找第一个 Excel 文件 ---
210	        async function findAndLoadFirstExcel() {
211	            if (!folderHandle) return;
212	            try {
213	                const entries = [];
214	                for await (const entry of folderHandle.values()) {
215	                    entries.push(entry);
216	                }
217	                const excelEntry = entries.find(e =>
218	                    e.kind === 'file' &&
219	                    (e.name.toLowerCase().endsWith('.xlsx') || e.name.toLowerCase().endsWith('.xls'))
220	                );
221	                if (excelEntry) {
222	                    excelFileName = excelEntry.name;
