235	        // --- 加载 Excel 文件（从 File 或 FileHandle）---
236	        async function loadExcelFile(fileOrHandle) {
237	            let file;
238	            if (fileOrHandle.getFile) {
239	                file = await fileOrHandle.getFile();
240	            } else {
241	                file = fileOrHandle;
