270	
271	        // --- 渲染指定工作表 ---
272	        function renderSheet(sheetName) {
273	            if (!workbookData) return;
274	            const worksheet = workbookData.Sheets[sheetName];
275	            // 转为二维数组（包含表头）
276	            const json = XLSX.utils.sheet_to_json(worksheet, { header: 1, defval: '' });
277	            if (!json || json.length === 0) {
278	                container.innerHTML = '<p style="color: #999;">该工作表为空</p>';
279	                currentHeaders = [];
280	                currentData = [];
281	                return;
282	            }
283	            // 第一行为表头
284	            const headers = json[0].map(h => String(h).trim());
285	            const dataRows = json.slice(1).map(row => {
286	                // 确保每行长度与表头一致
287	                while (row.length < headers.length) row.push('');
288	                return row.map(cell => String(cell).trim());
