297	        }
298	
299	        // --- 渲染表格（含排序）---
300	        function renderTable(headers, data) {
301	            let html = '<table><thead><tr>';
302	            headers.forEach((header, index) => {
303	                const sortClass = (index === sortColumn) ? (sortAsc ? 'sorted-asc' : 'sorted-desc') : '';
304	                html += `<th class="${sortClass}" data-col="${index}">${header}</th>`;
305	            });
306	            html += '</tr></thead><tbody>';
307	            data.forEach(row => {
308	                html += '<tr>';
309	                for (let i = 0; i < headers.length; i++) {
310	                    html += `<td>${row[i] || ''}</td>`;
311	                }
312	                html += '</tr>';
313	            });
314	            html += '</tbody></table>';
315	            container.innerHTML = html;
316	
317	            // 绑定表头点击排序
318	            document.querySelectorAll('th').forEach(th => {
319	                th.addEventListener('click', function () {
320	                    const col = parseInt(this.dataset.col);
321	                    if (sortColumn === col) sortAsc = !sortAsc;
322	                    else { sortColumn = col; sortAsc = true; }
323	                    applySort(sortColumn, sortAsc);
324	                });
325	            });
326	        }
327	
328	        function applySort(colIndex, ascending) {
329	            if (currentData.length === 0) return;
330	            const sorted = [...currentData].sort((a, b) => {
331	                const va = (a[colIndex] || '').toString();
332	                const vb = (b[colIndex] || '').toString();
333	                const na = parseFloat(va), nb = parseFloat(vb);
334	                if (!isNaN(na) && !isNaN(nb)) return ascending ? na - nb : nb - na;
335	                return ascending ? va.localeCompare(vb) : vb.localeCompare(va);
336	            });
337	            renderTable(currentHeaders, sorted);
338	        }
339	
340	        // --- 刷新：重新读取当前 Excel 文件（用于定时监控）---
341	        async function refreshExcel() {
342	            if (!folderHandle || !excelFileName) {
343	                statusDiv.textContent = '⚠️ 未授权或未选择文件';
344	                return;
345	            }
