352	            } catch (err) {
353	                if (err.name === 'NotFoundError') {
354	                    statusDiv.textContent = `⚠️ 文件 "${excelFileName}" 已不存在，重新查找...`;
355	                    await findAndLoadFirstExcel();
356	                } else {
357	                    statusDiv.textContent = `❌ 刷新失败: ${err.message}`;
358	                    console.error(err);
359	                }
360	            }
361	        }
